// TIME (T#... 32-bit) and LTIME (LTIME#... 64-bit nanosecond) literals & ops
VAR
    tCycle : TIME := T#100ms;
    ltAcc : LTIME := LTIME#0ms;
    ltLimit : LTIME := LTIME#10s;
END_VAR
ltAcc := ltAcc + LTIME#100ms;
IF ltAcc >= ltLimit THEN
    ltAcc := LTIME#0ms;
END_IF;

// Standard IEC TON timer: MUST invoke unconditionally OUTSIDE CASE/IF every scan!
VAR
    timer : TON;
    runTimer : BOOL;
END_VAR
// Control via boolean IN flag (never put timer(...) only inside an IF/CASE arm):
runTimer := (state = 1) AND NOT resetCmd;
timer(IN := runTimer, PT := T#2s);
IF timer.Q THEN
    // Timer expired; timer.ET holds elapsed time
END_IF;
